\set ON_ERROR_STOP on
begin;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
do $$
declare co uuid:=gen_random_uuid(); other_co uuid:=gen_random_uuid();u uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); customer uuid:=gen_random_uuid();s1 uuid;s2 uuid;n uuid;req uuid:=gen_random_uuid();ordinary uuid:=gen_random_uuid(); fake uuid:=gen_random_uuid(); result jsonb;d uuid;token uuid;dev jsonb;before_rows jsonb;
begin
 insert into companies values(co),(other_co);insert into profiles(id) values(u),(outsider),(customer);
 insert into company_members(company_id,profile_id,member_role) values(co,u,'dispatcher'),(other_co,outsider,'owner');
 perform set_config('request.jwt.claim.sub',u::text,true);execute 'set local role authenticated';
 s1:=save_staff_push_subscription(co,'https://web.push.apple.com/pilot-a',repeat('A',87),repeat('A',22),array['ai_needs_attention']);
 s2:=save_staff_push_subscription(co,'https://web.push.apple.com/pilot-b',repeat('A',87),repeat('A',22),array['ai_needs_attention']);
 begin perform create_staff_push_pilot(co,u,s1,req);raise exception 'browser create accepted';exception when insufficient_privilege then raise notice 'PASS browser cannot create pilot';end;
 execute 'reset role';update staff_notification_preferences set sms_enabled=true,telegram_enabled=true where company_id=co;
 insert into staff_notifications(id,company_id,recipient_profile_id,event_type,source_type,source_id,title,dedupe_key) values(ordinary,co,u,'ai_needs_attention','other',gen_random_uuid(),'Ordinary event','ordinary'),(fake,co,u,'ai_needs_attention','staff_push_pilot',gen_random_uuid(),'Forged marker','forged');
 select jsonb_agg(to_jsonb(x) order by id) into before_rows from staff_notification_deliveries x;
 execute 'set local role service_role';
 begin perform claim_staff_notification_deliveries(array['push'],3);raise exception 'general claim accepted';exception when insufficient_privilege then raise notice 'PASS general worker RPC disabled';end;
 begin perform prepare_staff_push_devices(gen_random_uuid(),gen_random_uuid());raise exception 'general fanout accepted';exception when insufficient_privilege then raise notice 'PASS general device fanout disabled';end;
 begin perform create_staff_push_pilot(co,customer,s1,req);raise exception 'customer accepted';exception when insufficient_privilege then raise notice 'PASS customer denied';end;
 begin perform create_staff_push_pilot(other_co,u,s1,req);raise exception 'cross-company accepted';exception when insufficient_privilege then raise notice 'PASS cross-company denied';end;
 begin perform create_staff_push_pilot(co,u,gen_random_uuid(),req);raise exception 'unowned subscription accepted';exception when insufficient_privilege then raise notice 'PASS unowned subscription denied';end;
 n:=create_staff_push_pilot(co,u,s1,req);
 perform pg_temp.ok(create_staff_push_pilot(co,u,s1,req)=n,'idempotent creation request');
 begin perform create_staff_push_pilot(co,u,s2,req);raise exception 'request retarget accepted';exception when insufficient_privilege then raise notice 'PASS creation request cannot retarget';end;
 begin perform claim_staff_push_pilot(ordinary,u,s1,co);raise exception 'ordinary event accepted';exception when insufficient_privilege then raise notice 'PASS real event denied';end;
 begin perform claim_staff_push_pilot(fake,u,s1,co);raise exception 'marker forgery accepted';exception when insufficient_privilege then raise notice 'PASS synthetic registry required';end;
 begin perform claim_staff_push_pilot(n,u,s2,co);raise exception 'wrong device accepted';exception when insufficient_privilege then raise notice 'PASS exact selected device required';end;
 begin perform claim_staff_push_pilot(n,outsider,s1,co);raise exception 'wrong recipient accepted';exception when insufficient_privilege then raise notice 'PASS exact recipient required';end;
 execute 'reset role';update staff_notification_preferences set push_enabled=false where company_id=co;
 execute 'set local role service_role';begin perform claim_staff_push_pilot(n,u,s1,co);raise exception 'optout accepted';exception when insufficient_privilege then raise notice 'PASS opt-out enforced';end;
 execute 'reset role';update staff_notification_preferences set push_enabled=true,quiet_start='00:00',quiet_end='00:00' where company_id=co;
 execute 'set local role service_role';begin perform claim_staff_push_pilot(n,u,s1,co);raise exception 'quiet accepted';exception when insufficient_privilege then raise notice 'PASS quiet hours enforced';end;
 execute 'reset role';update staff_notification_preferences set quiet_start=null,quiet_end=null where company_id=co;
 update company_members set member_status='suspended',suspended_at=clock_timestamp() where profile_id=u;
 execute 'set local role service_role';begin perform claim_staff_push_pilot(n,u,s1,co);raise exception 'suspended accepted';exception when insufficient_privilege then raise notice 'PASS suspended staff denied';end;
 execute 'reset role';update company_members set member_status='active',suspended_at=null where profile_id=u;
 execute 'set local role service_role';result:=claim_staff_push_pilot(n,u,s1,co);d:=(result->'claim'->>'id')::uuid;token:=(result->'claim'->>'lease_token')::uuid;
 perform pg_temp.ok(d is not null,'one exact pilot claim');
 perform pg_temp.ok(claim_staff_push_pilot(n,u,s1,co) is null,'second claim rejected');
 dev:=prepare_staff_push_pilot(d,token);perform pg_temp.ok(jsonb_array_length(dev)=1 and dev->0->>'id'=s1::text,'only selected device prepared');
 perform pg_temp.ok(reserve_staff_push_device(d,token,s1),'selected device reserved');
 perform pg_temp.ok(not reserve_staff_push_device(d,token,s2),'other owned device cannot reserve');
 perform pg_temp.ok(not reserve_staff_push_device(d,token,s1),'duplicate device attempt rejected');
 perform finish_staff_push_device(d,token,s1,'unknown',null);perform finish_staff_notification_delivery(d,token,'unknown');
 perform pg_temp.ok(claim_staff_push_pilot(n,u,s1,co) is null,'uncertain result never automatically retries');
 execute 'reset role';
 perform pg_temp.ok((select count(*)=1 and bool_and(channel='push') from staff_notification_deliveries where notification_id=n),'pilot has no SMS/Telegram deliveries');
 perform pg_temp.ok((select count(*)=1 from staff_push_delivery_devices where delivery_id=d),'single device log');
 perform pg_temp.ok((select jsonb_agg(to_jsonb(x) order by id) from staff_notification_deliveries x where notification_id<>n)=before_rows,'unrelated queue records unchanged');
 perform pg_temp.ok(not exists(select 1 from communication_messages),'no customer messages created');
 perform pg_temp.ok(not exists(select 1 from service_requests),'no fake Jobs created');
end$$;
rollback;
